CREATE TABLE IF NOT EXISTS m049_community_assets (id UUID PRIMARY KEY,asset_id TEXT NOT NULL UNIQUE,asset_type TEXT NOT NULL,name TEXT,location JSONB NOT NULL,village_id TEXT,condition TEXT NOT NULL CHECK(condition IN('excellent','good','fair','poor','critical')),custodian TEXT,utilization_pct NUMERIC CHECK(utilization_pct IS NULL OR utilization_pct BETWEEN 0 AND 100),maintenance_state TEXT,next_maintenance_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'active',properties JSONB NOT NULL DEFAULT '{}'::jsonb,created_by TEXT,updated_by TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),deleted_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS idx_m049_village_condition ON m049_community_assets(village_id,condition) WHERE deleted_at IS NULL;
